def top_k(lst, k):
    tmp = []
    while len(lst) > 0:
        tmp.append(max(lst))
        lst.remove(max(lst))
    return tmp[:k]

def top_k(lst, k):
    sort = []
    while lst: 
        biggest = lst[0]
        for element in lst:
            if element > biggest:
                biggest = element
            else:
                continue
        lst.remove(biggest)
        if len(sort) == k:
            break
        else:
            sort.append(biggest)
    return sort

